        Thread.sleep(delay);out.write(new byte[]{1,(byte)(rejected?1:0)});out.flush();c.authRejected=rejected;
        if(rejected){denied.incrementAndGet();return;}c.authAt=now();maxIdle=Math.max(maxIdle,idle().size());
        int version=in.read();if(version==-1){c.eofAt=now();return;}if(version!=5||in.readUnsignedByte()!=1)return;in.readUnsignedByte();int type=in.readUnsignedByte();byte[] address=new byte[type==1?4:type==4?16:in.readUnsignedByte()];in.readFully(address);
        String host=type==3?new String(address,StandardCharsets.US_ASCII):InetAddress.getByAddress(address).getHostAddress();int port=in.readUnsignedShort();
        if(!"127.0.0.1".equals(host)||!allowed.contains(port)){denied.incrementAndGet();out.write(new byte[]{5,2,0,1,0,0,0,0,0,0});out.flush();return;}
